// Resource-oriented routing with the Go 1.22 mux:
// nouns live in the path, HTTP verbs express the action.
mux := http.NewServeMux()
mux.HandleFunc("GET /users/{id}", getUser)     // read one
mux.HandleFunc("POST /users", createUser)      // create
mux.HandleFunc("PUT /users/{id}", replaceUser) // idempotent replace

func createUser(w http.ResponseWriter, r *http.Request) {
	id := store.Insert()
	w.Header().Set("Location", "/users/"+id)
	w.WriteHeader(http.StatusCreated) // 201, not 200
	_ = json.NewEncoder(w).Encode(map[string]string{"id": id})
}
